// ─────────────────────────────────────────────────────────────────
// 1) API-key authentication (default deny)
//    The caller must send header  x-api-key: <INVOICE_WEBHOOK_API_KEY>
// 2) Payload validation + normalization for the event router
// ─────────────────────────────────────────────────────────────────
const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};

const errors = [];

// --- API key check (default deny: nothing passes until the env var is set) ---
const providedKey = typeof headers['x-api-key'] === 'string' ? headers['x-api-key'].trim() : '';
const expectedKey = typeof $env.INVOICE_WEBHOOK_API_KEY === 'string' ? $env.INVOICE_WEBHOOK_API_KEY : '';
const authOk = Boolean(expectedKey) && providedKey === expectedKey;
if (!authOk) {
  errors.push('Invalid or missing API key. Send the header "x-api-key" with the value of the INVOICE_WEBHOOK_API_KEY environment variable.');
}

// --- Event type + payload extraction ---
const eventTypeRaw = body.eventType || body.event || body.type;
const eventType = typeof eventTypeRaw === 'string' ? eventTypeRaw.trim().toLowerCase() : '';

const KNOWN_EVENTS = ['invoice.created', 'payment.received', 'refund.created'];
if (!KNOWN_EVENTS.includes(eventType)) {
  errors.push(`Unsupported eventType "${eventType}". Expected one of: ${KNOWN_EVENTS.join(', ')}.`);
}

const payload = {};
if (eventType === 'invoice.created') {
  const inv = body.invoice || {};
  payload.invoice = inv;
  if (!inv.invoiceId) errors.push('invoice.invoiceId is required.');
  if (!inv.customerEmail) errors.push('invoice.customerEmail is required.');
  const hasItems = Array.isArray(inv.items) && inv.items.length > 0;
  const hasTotal = Number(inv.totalAmount) > 0;
  if (!hasItems && !hasTotal) errors.push('invoice.items[] (or invoice.totalAmount) is required.');
} else if (eventType === 'payment.received') {
  const pay = body.payment || {};
  payload.payment = pay;
  if (!pay.paymentId) errors.push('payment.paymentId is required.');
  if (!pay.invoiceId) errors.push('payment.invoiceId is required.');
  if (!(Number(pay.amount) > 0)) errors.push('payment.amount must be a number greater than zero.');
} else if (eventType === 'refund.created') {
  const ref = body.refund || {};
  payload.refund = ref;
  if (!ref.refundId) errors.push('refund.refundId is required.');
  if (!ref.invoiceId) errors.push('refund.invoiceId is required.');
  if (!(Number(ref.amount) > 0)) errors.push('refund.amount must be a number greater than zero.');
}

// Anything invalid is rerouted to the Switch fallback output -> HTTP 400
const normalizedEventType = errors.length === 0 ? eventType : 'invalid';

return [{
  json: {
    authOk,
    eventType: normalizedEventType,
    originalEventType: eventType,
    payload,
    errors,
    receivedAt: new Date().toISOString(),
  },
}];

// ─────────────────────────────────────────────────────────────────
// Build Invoice Record
// Normalizes the invoice payload, computes the totals and renders:
//  - invoiceHtml      → full standalone HTML document sent to PDFbro
//  - lineItemsTable   → items table reused in the customer email
// ─────────────────────────────────────────────────────────────────
const src = $('Validate Request').first().json.payload.invoice;

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const num = (v) => {
  const n = Number(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const money = (v) => num(v).toFixed(2);

const brand = $env.INVOICE_BRAND_NAME || 'Your Company';
const supportEmail = $env.SUPPORT_EMAIL || 'billing@example.com';

const items = Array.isArray(src.items) ? src.items : [];
let totalAmount = num(src.totalAmount);
if (items.length > 0) {
  // Line items win when provided: total = Σ quantity × unit price
  totalAmount = items.reduce((sum, it) => sum + num(it.quantity || 1) * num(it.unitPrice), 0);
}

const now = new Date();
const invoiceId = String(src.invoiceId);
const issueDate = src.issueDate || now.toISOString().slice(0, 10);
const dueDate = src.dueDate || issueDate;
const currency = String(src.currency || 'USD').toUpperCase();

const lineItemsRows = items.map((it) => {
  const qty = num(it.quantity || 1);
  const price = num(it.unitPrice);
  return `
    <tr>
      <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;">${esc(it.description || 'Item')}</td>
      <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;text-align:center;">${qty}</td>
      <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;text-align:right;">${currency} ${money(price)}</td>
      <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;text-align:right;"><strong>${currency} ${money(qty * price)}</strong></td>
    </tr>`;
}).join('');

const lineItemsTable = items.length > 0
  ? `
  <table style="width:100%;border-collapse:collapse;margin:24px 0;font-size:14px;">
    <thead>
      <tr style="background:#f8fafc;">
        <th style="padding:10px 8px;border-bottom:2px solid #0f172a;text-align:left;">Description</th>
        <th style="padding:10px 8px;border-bottom:2px solid #0f172a;text-align:center;">Qty</th>
        <th style="padding:10px 8px;border-bottom:2px solid #0f172a;text-align:right;">Unit price</th>
        <th style="padding:10px 8px;border-bottom:2px solid #0f172a;text-align:right;">Amount</th>
      </tr>
    </thead>
    <tbody>${lineItemsRows}</tbody>
  </table>`
  : '';

const invoiceHtml = `<!DOCTYPE html>
<html>
  <head>
    <meta charset="utf-8" />
    <title>Invoice ${esc(invoiceId)}</title>
  </head>
  <body style="margin:0;padding:40px;font-family:Helvetica,Arial,sans-serif;color:#0f172a;">
    <table style="width:100%;border-collapse:collapse;">
      <tr>
        <td style="vertical-align:top;">
          <div style="font-size:22px;font-weight:700;">${esc(brand)}</div>
          <div style="font-size:12px;color:#64748b;">${esc(supportEmail)}</div>
        </td>
        <td style="vertical-align:top;text-align:right;">
          <div style="font-size:28px;font-weight:700;">INVOICE</div>
          <div style="font-size:14px;color:#64748b;">#${esc(invoiceId)}</div>
        </td>
      </tr>
    </table>

    <table style="width:100%;border-collapse:collapse;margin-top:32px;font-size:14px;">
      <tr>
        <td style="vertical-align:top;width:50%;">
          <div style="color:#64748b;font-size:11px;text-transform:uppercase;letter-spacing:1px;">Billed to</div>
          <div style="font-weight:600;">${esc(src.customerName || src.customerEmail)}</div>
          <div>${esc(src.customerEmail)}</div>
          ${src.customerId ? `<div style="color:#64748b;">Customer ID: ${esc(src.customerId)}</div>` : ''}
        </td>
        <td style="vertical-align:top;text-align:right;">
          <div style="color:#64748b;font-size:11px;text-transform:uppercase;letter-spacing:1px;">Issue date</div>
          <div style="font-weight:600;">${esc(issueDate)}</div>
          <div style="margin-top:8px;color:#64748b;font-size:11px;text-transform:uppercase;letter-spacing:1px;">Due date</div>
          <div style="font-weight:600;">${esc(dueDate)}</div>
        </td>
      </tr>
    </table>

    ${lineItemsTable}

    <table style="width:300px;border-collapse:collapse;margin-left:auto;font-size:14px;">
      <tr>
        <td style="padding:8px 0;color:#64748b;">Total amount</td>
        <td style="padding:8px 0;text-align:right;font-size:20px;font-weight:700;">${currency} ${money(totalAmount)}</td>
      </tr>
    </table>

    ${src.notes ? `<p style="margin-top:32px;font-size:13px;color:#475569;"><strong>Notes:</strong> ${esc(src.notes)}</p>` : ''}

    <p style="margin-top:48px;font-size:12px;color:#94a3b8;">Invoice ${esc(invoiceId)} &middot; Generated ${now.toISOString()} &middot; ${esc(brand)}</p>
  </body>
</html>`;

return [{
  json: {
    invoiceId,
    customerId: String(src.customerId || ''),
    customerName: String(src.customerName || ''),
    customerEmail: String(src.customerEmail),
    issueDate,
    dueDate,
    currency,
    totalAmount: Number(money(totalAmount)),
    amountPaid: 0,
    balance: Number(money(totalAmount)),
    status: 'processing',
    itemCount: items.length,
    lineItemsTable,
    invoiceHtml,
    pdfFileName: `${invoiceId}.pdf`,
    notes: String(src.notes || ''),
    brand,
    supportEmail,
    createdAt: now.toISOString(),
  },
}];

// ─────────────────────────────────────────────────────────────────
// Build Invoice Email → exact Resend API payload
// (the next node simply POSTs JSON.stringify($json))
// ─────────────────────────────────────────────────────────────────
const inv = $('Build Invoice Record').first().json;

const from = $env.RESEND_FROM_EMAIL || 'Invoicing <onboarding@resend.dev>';
const to = inv.customerEmail;
const greeting = inv.customerName ? `Hi ${inv.customerName},` : 'Hello,';
const subject = `Invoice ${inv.invoiceId} from ${inv.brand} — ${inv.currency} ${inv.totalAmount.toFixed(2)}`;

const html = `
  <div style="font-family:Helvetica,Arial,sans-serif;color:#0f172a;max-width:560px;">
    <p>${greeting}</p>
    <p>Here is your invoice <strong>${inv.invoiceId}</strong>.</p>
    <p style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:12px 16px;">
      <strong>Total: ${inv.currency} ${inv.totalAmount.toFixed(2)}</strong><br />
      Issue date: ${inv.issueDate} &middot; Due date: ${inv.dueDate}
    </p>
    ${inv.lineItemsTable || ''}
    <p>Please arrange payment by the due date. A PDF copy of this invoice has been generated and archived for your records.</p>
    ${inv.notes ? `<p><em>${inv.notes}</em></p>` : ''}
    <p>If you have any questions, just reply to this email.</p>
    <p>Best regards,<br />${inv.brand}</p>
  </div>`;

const text = [
  greeting,
  '',
  `Invoice ${inv.invoiceId}`,
  `Total: ${inv.currency} ${inv.totalAmount.toFixed(2)}`,
  `Issue date: ${inv.issueDate}`,
  `Due date: ${inv.dueDate}`,
  inv.itemCount > 0 ? `Line items: ${inv.itemCount}` : '',
  '',
  'A PDF copy of this invoice has been generated and archived for your records.',
  '',
  'Best regards,',
  inv.brand,
].filter((line) => line !== '').join('\n');

return [{ json: { from, to, subject, html, text } }];

// ─────────────────────────────────────────────────────────────────
// Compute Payment Impact
// Applies the payment to the invoice balance (idempotency is already
// guaranteed by the duplicate check upstream).
//  - caps the applied amount at the outstanding balance (overpayment is reported)
//  - decides whether the invoice is now partially paid or fully paid
// ─────────────────────────────────────────────────────────────────
const row = $input.first().json; // invoice row read from the Invoices tab
const payment = $('Validate Request').first().json.payload.payment;

const num = (v) => {
  const n = Number(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const money = (v) => Number(v.toFixed(2));

const invoiceId = String(row['Invoice ID'] || payment.invoiceId);
const currency = String(row['Currency'] || payment.currency || 'USD').toUpperCase();

const total = num(row['Total Amount']);
const paidBefore = num(row['Amount Paid']);
const amount = num(payment.amount);

const paidAfterRaw = paidBefore + amount;
const overpaid = Math.max(0, paidAfterRaw - total);
const newAmountPaid = money(Math.min(total, paidAfterRaw));
const newBalance = money(Math.max(0, total - newAmountPaid));
const isFullyPaid = total > 0 && newBalance <= 0.005;

const invoiceStatusAfter = isFullyPaid
  ? 'paid'
  : (newAmountPaid > 0 ? 'partially_paid' : 'open');

return [{
  json: {
    invoiceId,
    paymentId: String(payment.paymentId),
    customerName: String(row['Customer Name'] || ''),
    customerEmail: String(row['Customer Email'] || ''),
    currency,
    invoiceTotal: money(total),
    amount: money(amount),
    paidBefore: money(paidBefore),
    newAmountPaid,
    newBalance,
    overpaid: money(overpaid),
    isFullyPaid,
    invoiceStatusBefore: String(row['Status'] || ''),
    invoiceStatusAfter,
    dueDate: String(row['Due Date'] || ''),
    method: String(payment.method || ''),
    receivedAt: payment.receivedAt || new Date().toISOString(),
  },
}];

// ─────────────────────────────────────────────────────────────────
// Build Final Payment Email → exact Resend API payload
// Sent when this payment settles the invoice in full.
// ─────────────────────────────────────────────────────────────────
const p = $('Compute Payment Impact').first().json;

const brand = $env.INVOICE_BRAND_NAME || 'Your Company';
const from = $env.RESEND_FROM_EMAIL || 'Invoicing <onboarding@resend.dev>';
const greeting = p.customerName ? `Hi ${p.customerName},` : 'Hello,';
const subject = `Invoice ${p.invoiceId} is fully paid — thank you!`;

const overpaidNote = p.overpaid > 0
  ? `<p style="color:#b45309;">Note: your payment exceeded the invoice total by <strong>${p.currency} ${p.overpaid.toFixed(2)}</strong>. Our team will contact you about the excess amount.</p>`
  : '';

const html = `
  <div style="font-family:Helvetica,Arial,sans-serif;color:#0f172a;max-width:560px;">
    <p>${greeting}</p>
    <p>Great news — invoice <strong>${p.invoiceId}</strong> is now <strong>fully paid</strong>. 🎉</p>
    <p style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;padding:12px 16px;">
      Invoice total: ${p.currency} ${p.invoiceTotal.toFixed(2)}<br />
      This payment: ${p.currency} ${p.amount.toFixed(2)}${p.method ? ` (via ${p.method})` : ''}<br />
      Outstanding balance: <strong>${p.currency} ${p.newBalance.toFixed(2)}</strong>
    </p>
    ${overpaidNote}
    <p>Thank you for your business! This email serves as your payment confirmation for the full amount.</p>
    <p>Best regards,<br />${brand}</p>
  </div>`;

const text = [
  greeting,
  '',
  `Great news — invoice ${p.invoiceId} is now fully paid.`,
  '',
  `Invoice total: ${p.currency} ${p.invoiceTotal.toFixed(2)}`,
  `This payment: ${p.currency} ${p.amount.toFixed(2)}${p.method ? ` (via ${p.method})` : ''}`,
  `Outstanding balance: ${p.currency} ${p.newBalance.toFixed(2)}`,
  p.overpaid > 0 ? `Note: your payment exceeded the invoice total by ${p.currency} ${p.overpaid.toFixed(2)}. Our team will contact you about the excess amount.` : '',
  '',
  'Thank you for your business! This email serves as your payment confirmation for the full amount.',
  '',
  'Best regards,',
  brand,
].filter((line) => line !== '').join('\n');

return [{ json: { from, to: p.customerEmail, subject, html, text } }];

// ─────────────────────────────────────────────────────────────────
// Build Payment Receipt Email → exact Resend API payload
// Sent when the invoice still has an outstanding balance.
// ─────────────────────────────────────────────────────────────────
const p = $('Compute Payment Impact').first().json;

const brand = $env.INVOICE_BRAND_NAME || 'Your Company';
const from = $env.RESEND_FROM_EMAIL || 'Invoicing <onboarding@resend.dev>';
const greeting = p.customerName ? `Hi ${p.customerName},` : 'Hello,';
const subject = `Payment received for invoice ${p.invoiceId} — ${p.currency} ${p.amount.toFixed(2)}`;

const html = `
  <div style="font-family:Helvetica,Arial,sans-serif;color:#0f172a;max-width:560px;">
    <p>${greeting}</p>
    <p>We confirm receipt of your payment of <strong>${p.currency} ${p.amount.toFixed(2)}</strong>${p.method ? ` (via ${p.method})` : ''} for invoice <strong>${p.invoiceId}</strong>. Thank you!</p>
    <p style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:12px 16px;">
      Invoice total: ${p.currency} ${p.invoiceTotal.toFixed(2)}<br />
      Amount paid so far: <strong>${p.currency} ${p.newAmountPaid.toFixed(2)}</strong><br />
      Remaining balance: <strong>${p.currency} ${p.newBalance.toFixed(2)}</strong>${p.dueDate ? `<br />Due date: ${p.dueDate}` : ''}
    </p>
    <p>The invoice is now marked as <strong>partially paid</strong>. We will confirm again once the remaining balance is settled.</p>
    <p>Best regards,<br />${brand}</p>
  </div>`;

const text = [
  greeting,
  '',
  `We confirm receipt of your payment of ${p.currency} ${p.amount.toFixed(2)}${p.method ? ` (via ${p.method})` : ''} for invoice ${p.invoiceId}. Thank you!`,
  '',
  `Invoice total: ${p.currency} ${p.invoiceTotal.toFixed(2)}`,
  `Amount paid so far: ${p.currency} ${p.newAmountPaid.toFixed(2)}`,
  `Remaining balance: ${p.currency} ${p.newBalance.toFixed(2)}`,
  p.dueDate ? `Due date: ${p.dueDate}` : '',
  '',
  'The invoice is now marked as partially paid.',
  '',
  'Best regards,',
  brand,
].filter((line) => line !== '').join('\n');

return [{ json: { from, to: p.customerEmail, subject, html, text } }];

// ─────────────────────────────────────────────────────────────────
// Compute Refund Impact
// Applies the refund to the invoice financials (idempotency is already
// guaranteed by the duplicate check upstream).
//  - a refund cannot return more than what was actually paid (excess is reported)
//  - updates the invoice financial status to refunded / partially refunded
// ─────────────────────────────────────────────────────────────────
const row = $input.first().json; // invoice row read from the Invoices tab
const refund = $('Validate Request').first().json.payload.refund;

const num = (v) => {
  const n = Number(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const money = (v) => Number(v.toFixed(2));

const invoiceId = String(row['Invoice ID'] || refund.invoiceId);
const currency = String(row['Currency'] || refund.currency || 'USD').toUpperCase();

const total = num(row['Total Amount']);
const paidBefore = num(row['Amount Paid']);
const amount = num(refund.amount);

// Refunds are capped at the amount actually paid on this invoice
const refundApplied = Math.min(amount, paidBefore);
const excessRefunded = Math.max(0, amount - paidBefore);

const newAmountPaid = money(Math.max(0, paidBefore - refundApplied));
const newBalance = money(Math.max(0, total - newAmountPaid));

const invoiceStatusAfter = newAmountPaid <= 0.005
  ? 'refunded'
  : 'partially_refunded';

return [{
  json: {
    invoiceId,
    refundId: String(refund.refundId),
    paymentId: String(refund.paymentId || ''),
    customerName: String(row['Customer Name'] || ''),
    customerEmail: String(row['Customer Email'] || ''),
    currency,
    invoiceTotal: money(total),
    refundAmount: money(amount),
    refundApplied: money(refundApplied),
    excessRefunded: money(excessRefunded),
    paidBefore: money(paidBefore),
    newAmountPaid,
    newBalance,
    invoiceStatusBefore: String(row['Status'] || ''),
    invoiceStatusAfter,
    reason: String(refund.reason || ''),
    refundedAt: refund.refundedAt || new Date().toISOString(),
  },
}];

// ─────────────────────────────────────────────────────────────────
// Build Refund Confirmation Email → exact Resend API payload
// ─────────────────────────────────────────────────────────────────
const r = $('Compute Refund Impact').first().json;

const brand = $env.INVOICE_BRAND_NAME || 'Your Company';
const from = $env.RESEND_FROM_EMAIL || 'Invoicing <onboarding@resend.dev>';
const greeting = r.customerName ? `Hi ${r.customerName},` : 'Hello,';
const subject = `Refund confirmation for invoice ${r.invoiceId} — ${r.currency} ${r.refundApplied.toFixed(2)}`;

const statusLine = r.invoiceStatusAfter === 'refunded'
  ? 'The invoice has been fully refunded and is now closed.'
  : `The invoice now has a remaining balance of ${r.currency} ${r.newBalance.toFixed(2)}.`;

const excessNote = r.excessRefunded > 0
  ? `<p style="color:#b45309;">Note: the refund amount exceeded what was paid on this invoice by <strong>${r.currency} ${r.excessRefunded.toFixed(2)}</strong>. Our team will contact you about the excess.</p>`
  : '';

const html = `
  <div style="font-family:Helvetica,Arial,sans-serif;color:#0f172a;max-width:560px;">
    <p>${greeting}</p>
    <p>We confirm that a refund of <strong>${r.currency} ${r.refundApplied.toFixed(2)}</strong> has been processed for invoice <strong>${r.invoiceId}</strong>${r.reason ? ` (${r.reason})` : ''}.</p>
    <p style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:12px 16px;">
      Invoice total: ${r.currency} ${r.invoiceTotal.toFixed(2)}<br />
      Refunded: <strong>${r.currency} ${r.refundApplied.toFixed(2)}</strong><br />
      Amount paid after refund: ${r.currency} ${r.newAmountPaid.toFixed(2)}<br />
      Invoice status: <strong>${r.invoiceStatusAfter.replace('_', ' ')}</strong>
    </p>
    ${excessNote}
    <p>${statusLine}</p>
    <p>Depending on your payment method, please allow 5–10 business days for the funds to appear.</p>
    <p>Best regards,<br />${brand}</p>
  </div>`;

const text = [
  greeting,
  '',
  `We confirm that a refund of ${r.currency} ${r.refundApplied.toFixed(2)} has been processed for invoice ${r.invoiceId}${r.reason ? ` (${r.reason})` : ''}.`,
  '',
  `Invoice total: ${r.currency} ${r.invoiceTotal.toFixed(2)}`,
  `Refunded: ${r.currency} ${r.refundApplied.toFixed(2)}`,
  `Amount paid after refund: ${r.currency} ${r.newAmountPaid.toFixed(2)}`,
  `Invoice status: ${r.invoiceStatusAfter.replace('_', ' ')}`,
  '',
  statusLine,
  'Depending on your payment method, please allow 5–10 business days for the funds to appear.',
  '',
  'Best regards,',
  brand,
].filter((line) => line !== '').join('\n');

return [{ json: { from, to: r.customerEmail, subject, html, text } }];
